const e="yIPTy4BqGSA",t="ch17-slow-english-practice-airport-essentials-for-traveling",c="b1",a="Slow English Practice | Airport ESSENTIALS for traveling ✈️",n="https://www.youtube.com/watch?v=yIPTy4BqGSA",r={podcastLabel:"MissHoney B1",titleZh:"慢速英語練習 |機場旅行必備品✈️",titleEn:"Slow English Practice | Airport ESSENTIALS for traveling ✈️",levelTag:"B1",topicTag:"travel"},i=JSON.parse(`[{"id":"scene-01","no":"01","titleZh":"第 1 段","titleEn":"Part 1","sentences":[{"en":"Hello and welcome back to my Slow English podcast.","tc":"哈囉，歡迎回到我的 Slow English podcast。","englishTokens":[{"type":"text","text":"Hello and welcome back to my Slow English podcast."}]},{"en":"Today we are at the airport.","tc":"今天我們在機場。","englishTokens":[{"type":"text","text":"Today we are at the airport."}]},{"en":"We are going to take a flight.","tc":"我們要搭飛機。","englishTokens":[{"type":"text","text":"We are going to "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-003-01"},{"type":"text","text":" a flight."}]},{"en":"Join us.","tc":"一起來吧。","englishTokens":[{"type":"text","text":"Join us."}]}],"tags":[]},{"id":"scene-02","no":"02","titleZh":"第 2 段","titleEn":"Part 2","sentences":[{"en":"The automatic doors slide open, and right away you see the FIDS board, the flight information display system, where you can see your flight status, whether it's on time, delayed, or cancelled.","tc":"自動門滑開，然後你馬上會看到 FIDS 看板，也就是航班資訊顯示系統；在那裡你可以看到你的航班狀態，看它是準時、延誤，還是取消。","englishTokens":[{"type":"text","text":"The "},{"type":"word","text":"automatic","targetId":"word-automatic","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-01"},{"type":"text","text":" doors slide open, and "},{"type":"phrase","text":"right away","targetId":"phrase-right-away","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-02"},{"type":"text","text":" you see the "},{"type":"word","text":"FIDS","targetId":"word-fids","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-03"},{"type":"text","text":" board, the flight information display system, where you can see your flight "},{"type":"word","text":"status","targetId":"word-status","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-04"},{"type":"text","text":", whether it's "},{"type":"phrase","text":"on time","targetId":"phrase-on-time","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-05"},{"type":"text","text":", "},{"type":"word","text":"delayed","targetId":"word-delayed","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-06"},{"type":"text","text":", or "},{"type":"word","text":"cancelled","targetId":"word-cancelled","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-005-07"},{"type":"text","text":"."}]},{"en":"Then we found our check-in counter.","tc":"接著我們找到了報到櫃台。","englishTokens":[{"type":"text","text":"Then we found our check-in "},{"type":"word","text":"counter","targetId":"word-counter","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-006-01"},{"type":"text","text":"."}]},{"en":"We were flying with AirAsia, so we had to find the AirAsia check-in counter.","tc":"我們搭的是 AirAsia，所以我們得找到 AirAsia 的報到櫃台。","englishTokens":[{"type":"text","text":"We were "},{"type":"usage","text":"flying","targetId":"usage-flying-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-007-01"},{"type":"text","text":" with AirAsia, so we had to find the AirAsia check-in counter."}]},{"en":"I am in line to check in.","tc":"我正在排隊報到。","englishTokens":[{"type":"text","text":"I am "},{"type":"phrase","text":"in line","targetId":"phrase-check-in","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-008-01"},{"type":"text","text":" to "},{"type":"phrase","text":"check in","targetId":"phrase-check-in","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-008-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-03","no":"03","titleZh":"第 3 段","titleEn":"Part 3","sentences":[{"en":"Some people prefer the self-check-in kiosk, but I don't like this self-check-in system as much.","tc":"有些人比較喜歡自助報到機，但我沒有那麼喜歡這種自助報到系統。","englishTokens":[{"type":"text","text":"Some people prefer the self-check-in "},{"type":"word","text":"kiosk","targetId":"word-kiosk","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-009-01"},{"type":"text","text":", but I don't like this self-check-in system as much."}]},{"en":"Sometimes it makes me nervous.","tc":"有時候它會讓我緊張。","englishTokens":[{"type":"text","text":"Sometimes it makes me "},{"type":"word","text":"nervous","targetId":"word-nervous","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-010-01"},{"type":"text","text":"."}]},{"en":"I prefer to check in at a counter with a real person.","tc":"我比較喜歡在櫃台跟真人報到。","englishTokens":[{"type":"text","text":"I prefer to check in at a counter with a "},{"type":"usage","text":"real","targetId":"usage-real-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-011-01"},{"type":"text","text":" person."}]},{"en":"What about you?","tc":"你呢？","englishTokens":[{"type":"text","text":"What about you?"}]}],"tags":[]},{"id":"scene-04","no":"04","titleZh":"第 4 段","titleEn":"Part 4","sentences":[{"en":"Do you prefer the check-in counter or the self-check-in kiosk?","tc":"你比較喜歡報到櫃台，還是自助報到機？","englishTokens":[{"type":"text","text":"Do you prefer the check-in "},{"type":"word","text":"counter","targetId":"word-counter","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-04-001-001"},{"type":"text","text":" or the self-check-in "},{"type":"word","text":"kiosk","targetId":"word-kiosk","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-04-001-002"},{"type":"text","text":"?"}]},{"en":"I am taking the escalator, the electric stairs.","tc":"我正在搭手扶梯，也就是電動樓梯。","englishTokens":[{"type":"text","text":"I am taking the "},{"type":"word","text":"escalator","targetId":"word-escalator","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-014-01"},{"type":"text","text":", the electric stairs."}]},{"en":"You can also take the elevator, but only if you need it.","tc":"你也可以搭電梯，但只有在你需要的時候才搭。","englishTokens":[{"type":"text","text":"You can also take the "},{"type":"word","text":"elevator","targetId":"word-elevator","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-015-01"},{"type":"text","text":", but only if you need it."}]},{"en":"Maybe if you have big luggage or you're in a wheelchair, but it's exclusive for people who need the elevator.","tc":"也許你有很大的行李，或你坐輪椅，不過它是專門給需要電梯的人使用的。","englishTokens":[{"type":"text","text":"Maybe if you have big "},{"type":"word","text":"luggage","targetId":"word-luggage","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-016-01"},{"type":"text","text":" or you're in a "},{"type":"word","text":"wheelchair","targetId":"word-wheelchair","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-016-02"},{"type":"text","text":", but it's "},{"type":"word","text":"exclusive","targetId":"word-exclusive","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-016-03"},{"type":"text","text":" for people who need the elevator."}]}],"tags":[]},{"id":"scene-05","no":"05","titleZh":"第 5 段","titleEn":"Part 5","sentences":[{"en":"I'm okay with taking the escalator, the electric stairs.","tc":"我搭手扶梯，也就是電動樓梯，就可以了。","englishTokens":[{"type":"text","text":"I'm okay with taking the "},{"type":"word","text":"escalator","targetId":"word-escalator","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-05-001-001"},{"type":"text","text":", the electric stairs."}]},{"en":"We got some lunch before our flight.","tc":"班機起飛前，我們吃了一些午餐。","englishTokens":[{"type":"text","text":"We got some lunch before our flight."}]},{"en":"We were close to international arrivals, but we had to get to international departures because we were departing, not arriving.","tc":"我們離國際抵達區很近，但我們得去國際出發區，因為我們是要出發，不是抵達。","englishTokens":[{"type":"text","text":"We were close to "},{"type":"word","text":"international","targetId":"word-international","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-019-01"},{"type":"text","text":" "},{"type":"word","text":"arrivals","targetId":"word-arrival","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-019-02"},{"type":"text","text":", but we had to get to international "},{"type":"word","text":"departures","targetId":"word-departure","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-019-03"},{"type":"text","text":" because we were departing, not arriving."}]},{"en":"I got my passport and my ticket ready, and we passed through the security checkpoint.","tc":"我把護照和機票準備好，然後我們通過安檢檢查站。","englishTokens":[{"type":"text","text":"I got my "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-020-01"},{"type":"text","text":" and my ticket ready, and we "},{"type":"phrase","text":"passed through","targetId":"phrase-passed-through","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-020-02"},{"type":"text","text":" the "},{"type":"word","text":"security","targetId":"word-security","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-020-03"},{"type":"text","text":" "},{"type":"word","text":"checkpoint","targetId":"word-checkpoint","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-020-04"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-06","no":"06","titleZh":"第 6 段","titleEn":"Part 6","sentences":[{"en":"There, you have to take out anything metal like keys, bracelets, coins or change, your computer or laptop, your phone, your headphones, and sometimes even your shoes.","tc":"在那裡，你必須拿出任何金屬物品，像鑰匙、手環、硬幣或零錢、電腦或筆電、手機、耳機，有時甚至還要脫鞋。","englishTokens":[{"type":"text","text":"There, you have to "},{"type":"phrase","text":"take out","targetId":"phrase-take-out","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-021-01"},{"type":"text","text":" anything "},{"type":"word","text":"metal","targetId":"word-metal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-021-02"},{"type":"text","text":" like keys, "},{"type":"word","text":"bracelets","targetId":"word-bracelet","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-021-03"},{"type":"text","text":", "},{"type":"word","text":"coins","targetId":"word-coin","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-021-04"},{"type":"text","text":" or change, your computer or "},{"type":"word","text":"laptop","targetId":"word-laptop","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-021-05"},{"type":"text","text":", your phone, your "},{"type":"word","text":"headphones","targetId":"word-headphones","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-021-06"},{"type":"text","text":", and sometimes even your shoes."}]},{"en":"The queue, or line, was very long, but once we got through security, we were inside the airport.","tc":"隊伍，也就是排隊的人龍，很長，但我們一通過安檢，就進到機場管制區裡了。","englishTokens":[{"type":"text","text":"The "},{"type":"word","text":"queue","targetId":"word-queue","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-022-01"},{"type":"text","text":", or line, was very long, but once we "},{"type":"phrase","text":"got through","targetId":"phrase-got-through","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-022-02"},{"type":"text","text":" security, we were inside the airport."}]},{"en":"I always love the duty-free stores.","tc":"我一直很喜歡免稅商店。","englishTokens":[{"type":"text","text":"I always love the "},{"type":"word","text":"duty-free","targetId":"word-duty-free","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-023-01"},{"type":"text","text":" stores."}]},{"en":"They're super expensive, but I like looking through each store while I wait.","tc":"它們超貴，但我喜歡一邊等，一邊逛每一間店。","englishTokens":[{"type":"text","text":"They're super expensive, but I like looking through each store while I wait."}]}],"tags":[]},{"id":"scene-07","no":"07","titleZh":"第 7 段","titleEn":"Part 7","sentences":[{"en":"We walked past Cartier and Starbucks as we made our way to our gate by following the signs with gate-number instructions on them.","tc":"我們經過 Cartier 和 Starbucks，照著帶有登機門號碼指示的標誌，往我們的登機門走。","englishTokens":[{"type":"text","text":"We walked past Cartier and Starbucks as we "},{"type":"phrase","text":"made our way","targetId":"phrase-made-our-way","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-025-01"},{"type":"text","text":" to our "},{"type":"word","text":"gate","targetId":"word-gate","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-025-02"},{"type":"text","text":" by following the signs with gate-number "},{"type":"word","text":"instructions","targetId":"word-instruction","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-025-03"},{"type":"text","text":" on them."}]},{"en":"It was super useful that they put how long a walk it was to each gate: 10 minutes, 5 minutes, or 1 minute.","tc":"它們標出走到每個登機門要多久，真的非常有用：10 分鐘、5 分鐘，或 1 分鐘。","englishTokens":[{"type":"text","text":"It was super "},{"type":"word","text":"useful","targetId":"word-useful","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-026-01"},{"type":"text","text":" that they put how long a walk it was to each gate: 10 minutes, 5 minutes, or 1 minute."}]},{"en":"That way, you're not super rushed or in a hurry to get to your gate when you still have lots of time to get there.","tc":"這樣一來，當你還有很多時間可以到登機門時，你就不會非常趕、非常匆忙。","englishTokens":[{"type":"text","text":"That way, you're not super "},{"type":"word","text":"rushed","targetId":"word-rushed","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-027-01"},{"type":"text","text":" or "},{"type":"phrase","text":"in a hurry","targetId":"phrase-in-a-hurry","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-027-02"},{"type":"text","text":" to get to your gate when you still have lots of time to get there."}]},{"en":"And you also know if you need to hurry and rush to your gate when it's only a five-minute walk.","tc":"當只要走五分鐘時，你也會知道自己需不需要趕快衝去登機門。","englishTokens":[{"type":"text","text":"And you also know if you need to hurry and rush to your "},{"type":"word","text":"gate","targetId":"word-gate","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-07-004-001"},{"type":"text","text":" when it's only a five-minute walk."}]}],"tags":[]},{"id":"scene-08","no":"08","titleZh":"第 8 段","titleEn":"Part 8","sentences":[{"en":"I usually eat something while I wait at my gate.","tc":"我通常會在登機門等待時吃點東西。","englishTokens":[{"type":"text","text":"I usually eat something while I wait at my "},{"type":"word","text":"gate","targetId":"word-gate","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-08-001-001"},{"type":"text","text":"."}]},{"en":"I wait at my boarding gate.","tc":"我在我的登機口等。","englishTokens":[{"type":"text","text":"I wait at my "},{"type":"word","text":"boarding","targetId":"word-boarding","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-030-01"},{"type":"text","text":" gate."}]},{"en":"It can be long sometimes, so I usually get some dessert.","tc":"有時候等待時間會很長，所以我通常會買一些甜點。","englishTokens":[{"type":"text","text":"It can be long sometimes, so I usually get some dessert."}]},{"en":"This one was a sweet bean dessert in Thailand.","tc":"這個是在泰國吃到的甜豆甜點。","englishTokens":[{"type":"text","text":"This one was a sweet bean dessert in Thailand."}]}],"tags":[]},{"id":"scene-09","no":"09","titleZh":"第 9 段","titleEn":"Part 9","sentences":[{"en":"It was so sweet.","tc":"它非常甜。","englishTokens":[{"type":"text","text":"It was so sweet."}]},{"en":"I loved it.","tc":"我很喜歡。","englishTokens":[{"type":"text","text":"I loved it."}]},{"en":"I'm curious.","tc":"我很好奇。","englishTokens":[{"type":"text","text":"I'm curious."}]},{"en":"Have you ever tried one of these little sweet treats?","tc":"你有試過這種小甜點嗎？","englishTokens":[{"type":"text","text":"Have you ever tried one of these little sweet treats?"}]}],"tags":[]},{"id":"scene-10","no":"10","titleZh":"第 10 段","titleEn":"Part 10","sentences":[{"en":"What do you think of them?","tc":"你覺得它們怎麼樣？","englishTokens":[{"type":"text","text":"What do you think of them?"}]},{"en":"Before boarding, I always go to the bathroom.","tc":"登機前，我一定會去上廁所。","englishTokens":[{"type":"text","text":"Before "},{"type":"word","text":"boarding","targetId":"word-boarding","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-10-002-001"},{"type":"text","text":", I always go to the bathroom."}]},{"en":"I make sure I have my two bags.","tc":"我會確認我有帶好兩個包。","englishTokens":[{"type":"text","text":"I make sure I have my two bags."}]},{"en":"And then we get on the airport shuttle bus.","tc":"然後我們上了機場接駁巴士。","englishTokens":[{"type":"text","text":"And then we get on the airport "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-040-01"},{"type":"text","text":" bus."}]}],"tags":[]},{"id":"scene-11","no":"11","titleZh":"第 11 段","titleEn":"Part 11","sentences":[{"en":"This shuttle takes us to the airplane.","tc":"這台接駁車會把我們載到飛機旁。","englishTokens":[{"type":"text","text":"This "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-11-001-001"},{"type":"text","text":" takes us to the airplane."}]},{"en":"Sometimes we take a shuttle to a plane, and sometimes you just go straight through and board the plane.","tc":"有時候我們會搭接駁車去飛機旁，有時候你就直接一路走過去登機。","englishTokens":[{"type":"text","text":"Sometimes we "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-11-002-001"},{"type":"text","text":" a "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-11-002-002"},{"type":"text","text":" to a plane, and sometimes you just go straight through and "},{"type":"usage","text":"board","targetId":"usage-board-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-11-002-003"},{"type":"text","text":" the plane."}]},{"en":"I prefer going straight to the plane, but sometimes you have to take a shuttle.","tc":"我比較喜歡直接走到飛機旁，但有時候你必須搭接駁車。","englishTokens":[{"type":"text","text":"I prefer going straight to the plane, but sometimes you have to "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-11-003-001"},{"type":"text","text":" a "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-11-003-002"},{"type":"text","text":"."}]},{"en":"The shuttle took all of the passengers to the plane, and then we waited in line to board.","tc":"接駁車把所有乘客載到飛機旁，然後我們排隊登機。","englishTokens":[{"type":"text","text":"The shuttle took all of the "},{"type":"word","text":"passengers","targetId":"word-passenger","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-044-01"},{"type":"text","text":" to the plane, and then we waited in line to "},{"type":"usage","text":"board","targetId":"usage-board-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-044-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-12","no":"12","titleZh":"第 12 段","titleEn":"Part 12","sentences":[{"en":"We had to climb stairs to board our plane.","tc":"我們必須爬樓梯登上飛機。","englishTokens":[{"type":"text","text":"We had to climb stairs to "},{"type":"usage","text":"board","targetId":"usage-board-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-12-001-001"},{"type":"text","text":" our plane."}]},{"en":"We walked through the aisle of the plane, and we put our luggage in the overhead bin right above our seats.","tc":"我們走過飛機的走道，然後把行李放進座位正上方的頭頂置物櫃。","englishTokens":[{"type":"text","text":"We walked through the "},{"type":"word","text":"aisle","targetId":"word-aisle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-046-01"},{"type":"text","text":" of the plane, and we put our luggage in the "},{"type":"word","text":"overhead","targetId":"word-overhead","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-046-02"},{"type":"text","text":" "},{"type":"word","text":"bin","targetId":"word-bin","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-046-03"},{"type":"text","text":" right above our seats."}]},{"en":"Here I am sitting in the aisle seat because I'm right next to the aisle.","tc":"你看，我坐在走道座位，因為我就在走道旁邊。","englishTokens":[{"type":"text","text":"Here I am sitting in the "},{"type":"word","text":"aisle","targetId":"word-aisle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-12-003-001"},{"type":"text","text":" seat because I'm right next to the "},{"type":"word","text":"aisle","targetId":"word-aisle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-12-003-002"},{"type":"text","text":"."}]},{"en":"This is my personal favorite seat because I can get up and go to the bathroom however many times I need, and I use the bathroom a lot.","tc":"這是我個人最喜歡的座位，因為我可以依照需要起身去上廁所，而且我很常使用廁所。","englishTokens":[{"type":"text","text":"This is my personal favorite seat because I can get up and go to the bathroom however many times I need, and I use the bathroom a lot."}]}],"tags":[]},{"id":"scene-13","no":"13","titleZh":"第 13 段","titleEn":"Part 13","sentences":[{"en":"I love a plane with screens for watching movies.","tc":"我喜歡有螢幕可以看電影的飛機。","englishTokens":[{"type":"text","text":"I love a plane with screens for watching movies."}]},{"en":"This plane was super empty, so I got a window seat.","tc":"這班飛機超空，所以我坐到了靠窗座位。","englishTokens":[{"type":"text","text":"This plane was super empty, so I got a window seat."}]},{"en":"The aisle seat and the middle seat were both empty, so I chose the window seat.","tc":"走道座位和中間座位都是空的，所以我選了靠窗座位。","englishTokens":[{"type":"text","text":"The "},{"type":"word","text":"aisle","targetId":"word-aisle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-13-003-001"},{"type":"text","text":" seat and the middle seat were both empty, so I chose the window seat."}]},{"en":"And then we are ready to take off.","tc":"然後我們就準備起飛了。","englishTokens":[{"type":"text","text":"And then we are ready to "},{"type":"phrase","text":"take off","targetId":"phrase-take-off","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-052-01"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-14","no":"14","titleZh":"第 14 段","titleEn":"Part 14","sentences":[{"en":"The plane drives on the runway for a little while, and once it gains enough speed, we take off.","tc":"飛機會在跑道上行駛一小段時間，等它取得足夠速度後，我們就起飛了。","englishTokens":[{"type":"text","text":"The plane drives on the "},{"type":"word","text":"runway","targetId":"word-runway","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-053-01"},{"type":"text","text":" for a little while, and once it gains enough "},{"type":"word","text":"speed","targetId":"word-speed","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-053-02"},{"type":"text","text":", we take off."}]},{"en":"Then I'm ready to put on my sleep mask and take a long nap.","tc":"接著我準備戴上眼罩，好好睡一大覺。","englishTokens":[{"type":"text","text":"Then I'm ready to "},{"type":"phrase","text":"put on","targetId":"phrase-put-on","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-054-01"},{"type":"text","text":" my sleep mask and take a long "},{"type":"word","text":"nap","targetId":"word-nap","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-054-02"},{"type":"text","text":"."}]},{"en":"The best way to spend a flight is sleeping through it.","tc":"度過飛行時間最好的方式，就是一路睡過去。","englishTokens":[{"type":"text","text":"The best way to spend a flight is "},{"type":"phrase","text":"sleeping through","targetId":"phrase-sleeping-through","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-055-01"},{"type":"text","text":" it."}]},{"en":"On long flights, they normally give you a pillow and a blanket.","tc":"長途飛行時，他們通常會給你枕頭和毯子。","englishTokens":[{"type":"text","text":"On long flights, they normally give you a "},{"type":"word","text":"pillow","targetId":"word-pillow","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-056-01"},{"type":"text","text":" and a "},{"type":"word","text":"blanket","targetId":"word-blanket","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-056-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-15","no":"15","titleZh":"第 15 段","titleEn":"Part 15","sentences":[{"en":"And you get to watch movies on the flight.","tc":"你也可以在飛機上看電影。","englishTokens":[{"type":"text","text":"And you get to watch movies on the flight."}]},{"en":"On long flights, I always bring my neck pillow, and I like watching the screen to see how far we have traveled.","tc":"長途飛行時，我一定會帶我的頸枕，而且我喜歡看螢幕，看看我們已經飛了多遠。","englishTokens":[{"type":"text","text":"On long flights, I always bring my neck "},{"type":"word","text":"pillow","targetId":"word-pillow","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-15-002-001"},{"type":"text","text":", and I like watching the screen to see how far we have traveled."}]},{"en":"I also like just looking at the world and learning about different countries that I've never heard of before.","tc":"我也喜歡只是看著世界，認識一些我以前從未聽過的不同國家。","englishTokens":[{"type":"text","text":"I also like just looking at the world and learning about different "},{"type":"word","text":"countries","targetId":"word-country","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-059-01"},{"type":"text","text":" that I've never heard of before."}]},{"en":"During my flights, I like to work on my computer.","tc":"飛行期間，我喜歡在電腦上工作。","englishTokens":[{"type":"text","text":"During my flights, I like to "},{"type":"phrase","text":"work on","targetId":"phrase-work-on","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-060-01"},{"type":"text","text":" my computer."}]}],"tags":[]},{"id":"scene-16","no":"16","titleZh":"第 16 段","titleEn":"Part 16","sentences":[{"en":"And during longer flights, I love how they tint the windows so that even if it's sunny outside, it will seem like it's nighttime.","tc":"而且在比較長的飛行中，我很喜歡他們把窗戶調暗；這樣就算外面陽光很大，看起來也會像晚上。","englishTokens":[{"type":"text","text":"And during longer flights, I love how they "},{"type":"word","text":"tint","targetId":"word-tint","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-061-01"},{"type":"text","text":" the windows so that even if it's sunny outside, it will seem like it's nighttime."}]},{"en":"It makes the sun look very pretty.","tc":"這讓太陽看起來非常漂亮。","englishTokens":[{"type":"text","text":"It makes the sun look very pretty."}]},{"en":"Then the sun rises, and I think it's almost time to land.","tc":"然後太陽升起，我想差不多該降落了。","englishTokens":[{"type":"text","text":"Then the sun rises, and I think it's almost time to "},{"type":"usage","text":"land","targetId":"usage-land-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-063-01"},{"type":"text","text":"."}]},{"en":"Finally, I wait my turn to get off the plane.","tc":"最後，我等輪到我下飛機。","englishTokens":[{"type":"text","text":"Finally, I wait my turn to "},{"type":"phrase","text":"get off","targetId":"phrase-get-off","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-064-01"},{"type":"text","text":" the plane."}]}],"tags":[]},{"id":"scene-17","no":"17","titleZh":"第 17 段","titleEn":"Part 17","sentences":[{"en":"I get my bags down from the overhead bin, and we walk out.","tc":"我把包從頭頂置物櫃拿下來，然後我們走出去。","englishTokens":[{"type":"text","text":"I get my bags down from the "},{"type":"word","text":"overhead","targetId":"word-overhead","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-17-001-001"},{"type":"text","text":" "},{"type":"word","text":"bin","targetId":"word-bin","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-17-001-002"},{"type":"text","text":", and we walk out."}]},{"en":"There is normally an escalator to get to immigration, or passport control.","tc":"通常會有手扶梯可以到移民檢查，也就是護照查驗處。","englishTokens":[{"type":"text","text":"There is normally an escalator to get to "},{"type":"word","text":"immigration","targetId":"word-immigration","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-066-01"},{"type":"text","text":", or "},{"type":"phrase","text":"passport control","targetId":"phrase-passport-control","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-066-02"},{"type":"text","text":"."}]},{"en":"You scan your passport and maybe talk to an immigration officer, and then you're there, in the country where you want to be.","tc":"你掃描護照，也可能會跟移民官說話，然後你就到了，到了你想抵達的那個國家。","englishTokens":[{"type":"text","text":"You scan your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-17-003-001"},{"type":"text","text":" and maybe talk to an "},{"type":"word","text":"immigration","targetId":"word-immigration","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-17-003-002"},{"type":"text","text":" officer, and then you're there, in the "},{"type":"word","text":"country","targetId":"word-country","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-17-003-003"},{"type":"text","text":" where you want to be."}]},{"en":"But if you have a layover, you normally still have to go through passport control, depending on the country, but you just don't leave the airport.","tc":"但如果你有轉機，你通常還是要通過護照查驗，這取決於國家，但你只是不離開機場。","englishTokens":[{"type":"text","text":"But if you have a "},{"type":"word","text":"layover","targetId":"word-layover","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-068-01"},{"type":"text","text":", you normally still have to go through passport control, depending on the country, but you just don't leave the airport."}]}],"tags":[]},{"id":"scene-18","no":"18","titleZh":"第 18 段","titleEn":"Part 18","sentences":[{"en":"You stay.","tc":"你會留在機場裡。","englishTokens":[{"type":"text","text":"You stay."}]},{"en":"When I have layovers, I usually stop by the food court, where I can find pizza, Mexican food, Chinese food, or McDonald's.","tc":"我有轉機時，通常會順道去美食街，在那裡我可以找到披薩、墨西哥食物、中式食物，或 McDonald's。","englishTokens":[{"type":"text","text":"When I have layovers, I usually "},{"type":"phrase","text":"stop by","targetId":"phrase-stop-by","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-070-01"},{"type":"text","text":" the food court, where I can find pizza, Mexican food, Chinese food, or McDonald's."}]},{"en":"This time I got an orange smoothie and a croissant sandwich.","tc":"這次我買了一杯柳橙冰沙和一個可頌三明治。","englishTokens":[{"type":"text","text":"This time I got an orange smoothie and a croissant sandwich."}]},{"en":"I eat during my layovers.","tc":"我會在轉機時吃東西。","englishTokens":[{"type":"text","text":"I eat during my layovers."}]}],"tags":[]},{"id":"scene-19","no":"19","titleZh":"第 19 段","titleEn":"Part 19","sentences":[{"en":"Then I make my way to my gate again.","tc":"然後我再次前往我的登機門。","englishTokens":[{"type":"text","text":"Then I make my way to my "},{"type":"word","text":"gate","targetId":"word-gate","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-19-001-001"},{"type":"text","text":" again."}]},{"en":"Now, this gate is to get me to my final destination, not just my layover.","tc":"現在，這個登機門是要帶我去最終目的地，不只是我的轉機點。","englishTokens":[{"type":"text","text":"Now, this gate is to get me to my "},{"type":"usage","text":"final","targetId":"usage-final-final-destination","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-074-01"},{"type":"text","text":" destination, not just my layover."}]},{"en":"I saw these super cool suitcases.","tc":"我看到了這些超酷的行李箱。","englishTokens":[{"type":"text","text":"I saw these super cool suitcases."}]},{"en":"You can drive them and sit down on them.","tc":"你可以開著它們，還可以坐在上面。","englishTokens":[{"type":"text","text":"You can drive them and "},{"type":"phrase","text":"sit down","targetId":"phrase-sit-down","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-076-01"},{"type":"text","text":" on them."}]}],"tags":[]},{"id":"scene-20","no":"20","titleZh":"第 20 段","titleEn":"Part 20","sentences":[{"en":"That way, you don't need to walk.","tc":"這樣你就不用走路。","englishTokens":[{"type":"text","text":"That way, you don't need to walk."}]},{"en":"Now, sometimes your next gate is at a different terminal.","tc":"現在，有時候你的下一個登機門會在不同的航廈。","englishTokens":[{"type":"text","text":"Now, sometimes your next gate is at a different "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-078-01"},{"type":"text","text":"."}]},{"en":"Maybe you're at Terminal 1, and your next flight leaves from Terminal 4.","tc":"也許你在第一航廈，而你的下一班飛機從第四航廈出發。","englishTokens":[{"type":"text","text":"Maybe you're at "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-20-003-001"},{"type":"text","text":" 1, and your next flight leaves from "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-20-003-002"},{"type":"text","text":" 4."}]},{"en":"Maybe you're at Terminal A, and you need to get to Terminal F, depending on the airport.","tc":"也許你在 A 航廈，而你需要到 F 航廈，這要看機場而定。","englishTokens":[{"type":"text","text":"Maybe you're at "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-20-004-001"},{"type":"text","text":" A, and you need to get to "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-20-004-002"},{"type":"text","text":" F, depending on the airport."}]}],"tags":[]},{"id":"scene-21","no":"21","titleZh":"第 21 段","titleEn":"Part 21","sentences":[{"en":"So, you need to take the airport train or airport shuttle.","tc":"所以你需要搭機場列車或機場接駁車。","englishTokens":[{"type":"text","text":"So, you need to "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-001-001"},{"type":"text","text":" the airport train or airport "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-001-002"},{"type":"text","text":"."}]},{"en":"So, you look at the signs and you follow them to the airport shuttle, and that takes you to your next terminal.","tc":"所以你看著標誌，跟著標誌走到機場接駁車那裡，然後它會帶你到下一個航廈。","englishTokens":[{"type":"text","text":"So, you look at the signs and you follow them to the airport "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-002-001"},{"type":"text","text":", and that takes you to your next "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-002-002"},{"type":"text","text":"."}]},{"en":"This flight left from Terminal 4.","tc":"這班飛機從第四航廈出發。","englishTokens":[{"type":"text","text":"This flight left from "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-003-001"},{"type":"text","text":" 4."}]},{"en":"So, I took the shuttle from Terminal 1 to Terminal 4.","tc":"所以我從第一航廈搭接駁車到第四航廈。","englishTokens":[{"type":"text","text":"So, I took the "},{"type":"word","text":"shuttle","targetId":"word-shuttle","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-004-001"},{"type":"text","text":" from "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-004-002"},{"type":"text","text":" 1 to "},{"type":"word","text":"Terminal","targetId":"word-terminal","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-21-004-003"},{"type":"text","text":" 4."}]}],"tags":[]},{"id":"scene-22","no":"22","titleZh":"第 22 段","titleEn":"Part 22","sentences":[{"en":"I love walking on the moving walkway, or the moving sidewalks.","tc":"我喜歡走在電動步道，也就是電動人行道上。","englishTokens":[{"type":"text","text":"I love walking on the moving walkway, or the moving sidewalks."}]},{"en":"I feel like I'm flying here.","tc":"我覺得我在這裡像是在飛。","englishTokens":[{"type":"text","text":"I feel like I'm "},{"type":"usage","text":"flying","targetId":"usage-flying-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-22-002-001"},{"type":"text","text":" here."}]},{"en":"I looked so tired because I barely got any sleep.","tc":"我看起來超累，因為我幾乎沒睡。","englishTokens":[{"type":"text","text":"I looked so tired because I barely got any sleep."}]},{"en":"So, I ordered a juice, and I edited for a little while.","tc":"所以我點了一杯果汁，然後剪輯了一會兒。","englishTokens":[{"type":"text","text":"So, I ordered a juice, and I edited for a little while."}]}],"tags":[]},{"id":"scene-23","no":"23","titleZh":"第 23 段","titleEn":"Part 23","sentences":[{"en":"Then it's time to wait at your gate.","tc":"接著就該在你的登機門等待了。","englishTokens":[{"type":"text","text":"Then it's time to wait at your "},{"type":"word","text":"gate","targetId":"word-gate","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-23-001-001"},{"type":"text","text":"."}]},{"en":"You don't want to wait somewhere else because you might miss your flight.","tc":"你不會想在別的地方等，因為你可能會錯過航班。","englishTokens":[{"type":"text","text":"You don't want to wait somewhere else because you might "},{"type":"usage","text":"miss","targetId":"usage-miss-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-090-01"},{"type":"text","text":" your flight."}]},{"en":"Finally, you land at your final destination, whether that's home, a place you want to visit, or the home of someone you love.","tc":"最後，你抵達你的最終目的地，不管那是家、你想去拜訪的地方，還是你愛的人的家。","englishTokens":[{"type":"text","text":"Finally, you "},{"type":"usage","text":"land","targetId":"usage-land-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-23-003-001"},{"type":"text","text":" at your "},{"type":"usage","text":"final","targetId":"usage-final-final-destination","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-23-003-002"},{"type":"text","text":" destination, whether that's home, a place you want to visit, or the home of someone you love."}]},{"en":"But if you checked a bag, then you need to go get your bag at the luggage carousel.","tc":"但如果你托運了行李，那你就需要去行李轉盤領你的包。","englishTokens":[{"type":"text","text":"But if you "},{"type":"usage","text":"checked","targetId":"usage-checked-checked-a-bag","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-092-01"},{"type":"text","text":" a bag, then you need to go get your bag at the luggage "},{"type":"word","text":"carousel","targetId":"word-carousel","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-092-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-24","no":"24","titleZh":"第 24 段","titleEn":"Part 24","sentences":[{"en":"You check the carousel screen and your flight number to make sure they match, and you wait until you see your luggage pass by.","tc":"你查看行李轉盤螢幕和你的航班號碼，確認它們相符，然後一直等到你看到你的行李經過。","englishTokens":[{"type":"text","text":"You check the carousel screen and your flight number to make sure they match, and you wait until you see your luggage "},{"type":"phrase","text":"pass by","targetId":"phrase-pass-by","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-093-01"},{"type":"text","text":"."}]},{"en":"I don't know about you, but I love my airport outfits.","tc":"我不知道你怎麼想，但我很喜歡我的機場穿搭。","englishTokens":[{"type":"text","text":"I don't know about you, but I love my airport outfits."}]},{"en":"They are super cozy.","tc":"它們超舒服。","englishTokens":[{"type":"text","text":"They are super "},{"type":"word","text":"cozy","targetId":"word-cozy","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-095-01"},{"type":"text","text":"."}]},{"en":"Here's one.","tc":"這是一套。","englishTokens":[{"type":"text","text":"Here's one."}]}],"tags":[]},{"id":"scene-25","no":"25","titleZh":"第 25 段","titleEn":"Part 25","sentences":[{"en":"It is a baggy shirt, my high bun, and some very loose pants.","tc":"它是一件寬鬆的襯衫、我的高包頭，還有一件非常寬鬆的褲子。","englishTokens":[{"type":"text","text":"It is a "},{"type":"word","text":"baggy","targetId":"word-baggy","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-097-01"},{"type":"text","text":" shirt, my high bun, and some very loose pants."}]},{"en":"Now, here's a little story time about when I lost my passport in Beijing.","tc":"現在，這裡有一個我在北京弄丟護照的小故事。","englishTokens":[{"type":"text","text":"Now, here's a little story time about when I lost my "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-25-002-001"},{"type":"text","text":" in Beijing."}]},{"en":"Have you ever lost your passport?","tc":"你曾經弄丟過護照嗎？","englishTokens":[{"type":"text","text":"Have you ever lost your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-25-003-001"},{"type":"text","text":"?"}]},{"en":"I am at the airport.","tc":"我在機場。","englishTokens":[{"type":"text","text":"I am at the airport."}]}],"tags":[]},{"id":"scene-26","no":"26","titleZh":"第 26 段","titleEn":"Part 26","sentences":[{"en":"This is my airport outfit.","tc":"這是我的機場穿搭。","englishTokens":[{"type":"text","text":"This is my airport outfit."}]},{"en":"What do you wear to the airport?","tc":"你去機場時會穿什麼？","englishTokens":[{"type":"text","text":"What do you wear to the airport?"}]},{"en":"I feel so comfy, like I'm wearing a blanket.","tc":"我覺得好舒服，像是穿著一條毯子。","englishTokens":[{"type":"text","text":"I feel so comfy, like I'm wearing a "},{"type":"word","text":"blanket","targetId":"word-blanket","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-26-003-001"},{"type":"text","text":"."}]},{"en":"I have two big backpacks.","tc":"我有兩個大背包。","englishTokens":[{"type":"text","text":"I have two big backpacks."}]}],"tags":[]},{"id":"scene-27","no":"27","titleZh":"第 27 段","titleEn":"Part 27","sentences":[{"en":"One is a carry-on, and the other one is a personal item.","tc":"一個是隨身行李，另一個是個人物品。","englishTokens":[{"type":"text","text":"One is a "},{"type":"word","text":"carry-on","targetId":"word-carry-on","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-105-01"},{"type":"text","text":", and the other one is a personal "},{"type":"word","text":"item","targetId":"word-item","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-105-02"},{"type":"text","text":"."}]},{"en":"I am at the Beijing airport, but I'm not staying here.","tc":"我在北京機場，但我不會待在這裡。","englishTokens":[{"type":"text","text":"I am at the Beijing airport, but I'm not staying here."}]},{"en":"Beijing is just my layover on the way to Bangkok, Thailand.","tc":"北京只是我前往泰國曼谷路上的轉機點。","englishTokens":[{"type":"text","text":"Beijing is just my "},{"type":"word","text":"layover","targetId":"word-layover","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-27-003-001"},{"type":"text","text":" on the way to Bangkok, Thailand."}]},{"en":"My final destination is Bangkok, Thailand.","tc":"我的最終目的地是泰國曼谷。","englishTokens":[{"type":"text","text":"My "},{"type":"usage","text":"final","targetId":"usage-final-final-destination","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-27-004-001"},{"type":"text","text":" destination is Bangkok, Thailand."}]}],"tags":[]},{"id":"scene-28","no":"28","titleZh":"第 28 段","titleEn":"Part 28","sentences":[{"en":"But don't worry, I will be back in Beijing in one week to visit the city.","tc":"但別擔心，一週後我會回到北京參觀這座城市。","englishTokens":[{"type":"text","text":"But don't worry, I will be back in Beijing in one week to visit the city."}]},{"en":"My flight from Tijuana to Beijing was 12 hours long.","tc":"我從 Tijuana 飛到北京的航班長達 12 小時。","englishTokens":[{"type":"text","text":"My flight from Tijuana to Beijing was 12 hours long."}]},{"en":"I'm super jet-lagged, and I still have another 4 hours.","tc":"我超級有時差，而且我還有另外 4 個小時。","englishTokens":[{"type":"text","text":"I'm super "},{"type":"word","text":"jet-lagged","targetId":"word-jet-lagged","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-111-01"},{"type":"text","text":", and I still have another 4 hours."}]},{"en":"And actually, I was so stressed out about getting Wi-Fi to work, working on my videos, editing, and answering emails that I forgot my passport.","tc":"其實，我當時非常焦慮，忙著讓 Wi-Fi 能用、處理影片、剪輯和回覆電子郵件，結果我忘了我的護照。","englishTokens":[{"type":"text","text":"And actually, I was so "},{"type":"phrase","text":"stressed out","targetId":"phrase-stressed-out","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-112-01"},{"type":"text","text":" about getting Wi-Fi to work, working on my videos, editing, and answering emails that I forgot my passport."}]}],"tags":[]},{"id":"scene-29","no":"29","titleZh":"第 29 段","titleEn":"Part 29","sentences":[{"en":"I left it on the table, and I walked away searching for Wi-Fi.","tc":"我把它留在桌上，然後走開去找 Wi-Fi。","englishTokens":[{"type":"text","text":"I left it on the table, and I walked away searching for Wi-Fi."}]},{"en":"I realized I lost my passport, and I ran around desperately, looking and asking everyone, but nobody spoke English.","tc":"我發現我弄丟護照後，就慌張地到處跑，一邊找一邊問每個人，但沒有人會說英文。","englishTokens":[{"type":"text","text":"I realized I lost my passport, and I ran around "},{"type":"word","text":"desperately","targetId":"word-desperately","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-114-01"},{"type":"text","text":", looking and asking everyone, but nobody spoke English."}]},{"en":"So, I was super stressed out just a minute ago.","tc":"所以，就在一分鐘前我還超級焦慮。","englishTokens":[{"type":"text","text":"So, I was super "},{"type":"phrase","text":"stressed out","targetId":"phrase-stressed-out","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-29-003-001"},{"type":"text","text":" just a minute ago."}]},{"en":"Now, I'm a lot more relaxed.","tc":"現在，我放鬆多了。","englishTokens":[{"type":"text","text":"Now, I'm a lot more relaxed."}]}],"tags":[]},{"id":"scene-30","no":"30","titleZh":"第 30 段","titleEn":"Part 30","sentences":[{"en":"I don't have Wi-Fi, but now I know it could be much worse.","tc":"我沒有 Wi-Fi，但現在我知道情況本來可能糟得多。","englishTokens":[{"type":"text","text":"I don't have Wi-Fi, but now I know it could be much worse."}]},{"en":"Sometimes life just teaches you lessons that you need at that moment to really appreciate what you do have and not stress about little things like Wi-Fi.","tc":"有時候人生就是會在你需要的那一刻教你一些課，讓你真正感謝自己所擁有的東西，而不要為 Wi-Fi 這種小事緊張。","englishTokens":[{"type":"text","text":"Sometimes life just teaches you lessons that you need at that moment to really "},{"type":"word","text":"appreciate","targetId":"word-appreciate","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-118-01"},{"type":"text","text":" what you do have and not stress about little things like Wi-Fi."}]},{"en":"Have you ever lost your passport before?","tc":"你以前曾經弄丟過護照嗎？","englishTokens":[{"type":"text","text":"Have you ever lost your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-30-003-001"},{"type":"text","text":" before?"}]},{"en":"All right, guys.","tc":"好了，各位。","englishTokens":[{"type":"text","text":"All right, guys."}]}],"tags":[]},{"id":"scene-31","no":"31","titleZh":"第 31 段","titleEn":"Part 31","sentences":[{"en":"Thank you so much for joining me.","tc":"非常謝謝你們加入我。","englishTokens":[{"type":"text","text":"Thank you so much for joining me."}]},{"en":"I hope you learned some new English vocabulary, and I hope this helps you in the future if you're ever traveling anywhere and you need to find your passport, your gate number, or your terminal.","tc":"希望你們學到一些新的英文單字，也希望將來如果你們去任何地方旅行，需要找到護照、登機門號碼或航廈時，這會幫上忙。","englishTokens":[{"type":"text","text":"I hope you learned some new English "},{"type":"word","text":"vocabulary","targetId":"word-vocabulary","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-122-01"},{"type":"text","text":", and I hope this helps you in the future if you're ever traveling anywhere and you need to find your passport, your gate number, or your terminal."}]},{"en":"If you're feeling nervous about traveling somewhere and not knowing what to do, use this video to guide you through that unknown vocabulary at airports.","tc":"如果你因為要去某個地方旅行、卻不知道該怎麼做而感到緊張，就用這部影片帶你理解機場裡那些陌生的單字。","englishTokens":[{"type":"text","text":"If you're feeling "},{"type":"word","text":"nervous","targetId":"word-nervous","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-31-003-001"},{"type":"text","text":" about traveling somewhere and not knowing what to do, use this video to guide you through that unknown "},{"type":"word","text":"vocabulary","targetId":"word-vocabulary","instanceId":"marker-b1-ch17-slow-english-practice-airport-essentials-for-traveling-scene-31-003-002"},{"type":"text","text":" at airports."}]},{"en":"Have a beautiful day, and don't stop learning.","tc":"祝你有美好的一天，不要停止學習。","englishTokens":[{"type":"text","text":"Have a beautiful day, and don't stop learning."}]}],"tags":[]},{"id":"scene-32","no":"32","titleZh":"第 32 段","titleEn":"Part 32","sentences":[{"en":"See you next time.","tc":"下次見。","englishTokens":[{"type":"text","text":"See you next time."}]},{"en":"Bye.","tc":"拜拜。","englishTokens":[{"type":"text","text":"Bye."}]}],"tags":[]}]`),s=[{title:"B1 重點單字",items:[{id:"word-automatic",lemma:"automatic",english:"automatic",kk:"ˌɔtəˈmætɪk",partOfSpeech:"形容詞",meaning:"自動的",highlight:!0},{id:"word-fids",lemma:"fids",english:"FIDS",kk:"ˈɛf ˈaɪ ˈdi ˈɛs",partOfSpeech:"縮寫名詞",meaning:"航班資訊顯示系統",highlight:!0},{id:"word-status",lemma:"status",english:"status",kk:"ˈstetəs",partOfSpeech:"名詞",meaning:"狀態",highlight:!0},{id:"word-delayed",lemma:"delayed",english:"delayed",kk:"dɪˈled",partOfSpeech:"形容詞",meaning:"延誤的",highlight:!0},{id:"word-cancelled",lemma:"cancelled",english:"cancelled",kk:"ˈkænsəld",partOfSpeech:"形容詞",meaning:"取消的",highlight:!0},{id:"word-counter",lemma:"counter",english:"counter",kk:"ˈkaʊntɚ",partOfSpeech:"名詞",meaning:"櫃台",highlight:!0},{id:"word-kiosk",lemma:"kiosk",english:"kiosk",kk:"ˈkiɑsk",partOfSpeech:"名詞",meaning:"自助服務機；小亭",highlight:!0},{id:"word-nervous",lemma:"nervous",english:"nervous",kk:"ˈnɝvəs",partOfSpeech:"形容詞",meaning:"緊張的",highlight:!0},{id:"word-escalator",lemma:"escalator",english:"escalator",kk:"ˈɛskəˌletɚ",partOfSpeech:"名詞",meaning:"手扶梯",highlight:!0},{id:"word-elevator",lemma:"elevator",english:"elevator",kk:"ˈɛləˌvetɚ",partOfSpeech:"名詞",meaning:"電梯",highlight:!0},{id:"word-luggage",lemma:"luggage",english:"luggage",kk:"ˈlʌɡɪdʒ",partOfSpeech:"名詞",meaning:"行李",highlight:!0},{id:"word-wheelchair",lemma:"wheelchair",english:"wheelchair",kk:"ˈhwilˌtʃɛr",partOfSpeech:"名詞",meaning:"輪椅",highlight:!0},{id:"word-exclusive",lemma:"exclusive",english:"exclusive",kk:"ɪkˈsklusɪv",partOfSpeech:"形容詞",meaning:"專用的；排他的",highlight:!0},{id:"word-international",lemma:"international",english:"international",kk:"ˌɪntɚˈnæʃənəl",partOfSpeech:"形容詞",meaning:"國際的",highlight:!0},{id:"word-arrival",lemma:"arrival",english:"arrivals",kk:"əˈraɪvəlz",partOfSpeech:"名詞",meaning:"抵達區；到達",highlight:!0},{id:"word-departure",lemma:"departure",english:"departures",kk:"dɪˈpɑrtʃɚz",partOfSpeech:"名詞",meaning:"出發區；離境",highlight:!0},{id:"word-passport",lemma:"passport",english:"passport",kk:"ˈpæsˌpɔrt",partOfSpeech:"名詞",meaning:"護照",highlight:!0},{id:"word-security",lemma:"security",english:"security",kk:"sɪˈkjʊrəti",partOfSpeech:"名詞",meaning:"安檢；安全",highlight:!0},{id:"word-checkpoint",lemma:"checkpoint",english:"checkpoint",kk:"ˈtʃɛkˌpɔɪnt",partOfSpeech:"名詞",meaning:"檢查站",highlight:!0},{id:"word-metal",lemma:"metal",english:"metal",kk:"ˈmɛtəl",partOfSpeech:"名詞",meaning:"金屬",highlight:!0},{id:"word-bracelet",lemma:"bracelet",english:"bracelets",kk:"ˈbresləts",partOfSpeech:"名詞",meaning:"手環；手鍊",highlight:!0},{id:"word-coin",lemma:"coin",english:"coins",kk:"kɔɪnz",partOfSpeech:"名詞",meaning:"硬幣",highlight:!0},{id:"word-laptop",lemma:"laptop",english:"laptop",kk:"ˈlæpˌtɑp",partOfSpeech:"名詞",meaning:"筆記型電腦",highlight:!0},{id:"word-headphones",lemma:"headphones",english:"headphones",kk:"ˈhɛdˌfonz",partOfSpeech:"名詞",meaning:"耳機",highlight:!0},{id:"word-queue",lemma:"queue",english:"queue",kk:"kju",partOfSpeech:"名詞",meaning:"隊伍；人龍",highlight:!0},{id:"word-duty-free",lemma:"duty-free",english:"duty-free",kk:"ˌdutiˈfri",partOfSpeech:"形容詞",meaning:"免稅的",highlight:!0},{id:"word-gate",lemma:"gate",english:"gate",kk:"ɡet",partOfSpeech:"名詞",meaning:"登機門",highlight:!0},{id:"word-instruction",lemma:"instruction",english:"instructions",kk:"ɪnˈstrʌkʃənz",partOfSpeech:"名詞",meaning:"指示；說明",highlight:!0},{id:"word-useful",lemma:"useful",english:"useful",kk:"ˈjusfəl",partOfSpeech:"形容詞",meaning:"有用的",highlight:!0},{id:"word-rushed",lemma:"rushed",english:"rushed",kk:"rʌʃt",partOfSpeech:"形容詞",meaning:"匆忙的；趕時間的",highlight:!0},{id:"word-boarding",lemma:"boarding",english:"boarding",kk:"ˈbɔrdɪŋ",partOfSpeech:"形容詞",meaning:"登機的",highlight:!0},{id:"word-shuttle",lemma:"shuttle",english:"shuttle",kk:"ˈʃʌtəl",partOfSpeech:"名詞",meaning:"接駁車",highlight:!0},{id:"word-passenger",lemma:"passenger",english:"passengers",kk:"ˈpæsəndʒɚz",partOfSpeech:"名詞",meaning:"乘客",highlight:!0},{id:"word-aisle",lemma:"aisle",english:"aisle",kk:"aɪl",partOfSpeech:"名詞",meaning:"走道",highlight:!0},{id:"word-overhead",lemma:"overhead",english:"overhead",kk:"ˈovɚˌhɛd",partOfSpeech:"形容詞",meaning:"頭頂上的",highlight:!0},{id:"word-bin",lemma:"bin",english:"bin",kk:"bɪn",partOfSpeech:"名詞",meaning:"置物櫃；箱",highlight:!0},{id:"word-runway",lemma:"runway",english:"runway",kk:"ˈrʌnˌwe",partOfSpeech:"名詞",meaning:"跑道",highlight:!0},{id:"word-speed",lemma:"speed",english:"speed",kk:"spid",partOfSpeech:"名詞",meaning:"速度",highlight:!0},{id:"word-nap",lemma:"nap",english:"nap",kk:"næp",partOfSpeech:"名詞",meaning:"小睡",highlight:!0},{id:"word-pillow",lemma:"pillow",english:"pillow",kk:"ˈpɪlo",partOfSpeech:"名詞",meaning:"枕頭",highlight:!0},{id:"word-blanket",lemma:"blanket",english:"blanket",kk:"ˈblæŋkɪt",partOfSpeech:"名詞",meaning:"毯子",highlight:!0},{id:"word-country",lemma:"country",english:"countries",kk:"ˈkʌntriz",partOfSpeech:"名詞",meaning:"國家",highlight:!0},{id:"word-tint",lemma:"tint",english:"tint",kk:"tɪnt",partOfSpeech:"動詞",meaning:"把顏色調暗；染色",highlight:!0},{id:"word-immigration",lemma:"immigration",english:"immigration",kk:"ˌɪməˈɡreʃən",partOfSpeech:"名詞",meaning:"移民檢查；入境審查",highlight:!0},{id:"word-layover",lemma:"layover",english:"layover",kk:"ˈleˌovɚ",partOfSpeech:"名詞",meaning:"轉機停留",highlight:!0},{id:"word-terminal",lemma:"terminal",english:"terminal",kk:"ˈtɝmənəl",partOfSpeech:"名詞",meaning:"航廈",highlight:!0},{id:"word-carousel",lemma:"carousel",english:"carousel",kk:"ˌkærəˈsɛl",partOfSpeech:"名詞",meaning:"行李轉盤",highlight:!0},{id:"word-cozy",lemma:"cozy",english:"cozy",kk:"ˈkozi",partOfSpeech:"形容詞",meaning:"舒適的",highlight:!0},{id:"word-baggy",lemma:"baggy",english:"baggy",kk:"ˈbæɡi",partOfSpeech:"形容詞",meaning:"寬鬆的",highlight:!0},{id:"word-carry-on",lemma:"carry-on",english:"carry-on",kk:"ˈkæriˌɑn",partOfSpeech:"名詞",meaning:"隨身行李",highlight:!0},{id:"word-item",lemma:"item",english:"item",kk:"ˈaɪtəm",partOfSpeech:"名詞",meaning:"物品",highlight:!0},{id:"word-jet-lagged",lemma:"jet-lagged",english:"jet-lagged",kk:"ˈdʒɛtˌlæɡd",partOfSpeech:"形容詞",meaning:"有時差的；因時差而疲累的",highlight:!0},{id:"word-desperately",lemma:"desperately",english:"desperately",kk:"ˈdɛspərɪtli",partOfSpeech:"副詞",meaning:"拼命地；慌張地",highlight:!0},{id:"word-appreciate",lemma:"appreciate",english:"appreciate",kk:"əˈpriʃiˌet",partOfSpeech:"動詞",meaning:"感激；珍惜",highlight:!0},{id:"word-vocabulary",lemma:"vocabulary",english:"vocabulary",kk:"voˈkæbjəˌlɛri",partOfSpeech:"名詞",meaning:"字彙；單字",highlight:!0}]}],o=[{id:"phrase-right-away",phrase:"right away",meaning:"立刻；馬上",examples:[{en:"__right away__ you see the **FIDS** board.",tc:"立刻；馬上"}]},{id:"phrase-on-time",phrase:"on time",meaning:"準時",examples:[{en:"Whether it's __on time__, **delayed**, or **cancelled**.",tc:"準時"}]},{id:"phrase-in-line",phrase:"in line",meaning:"排隊",examples:[{en:"I am __in line__ to __check in__.",tc:"排隊"}]},{id:"phrase-check-in",phrase:"check in",meaning:"報到；辦理登機手續",examples:[{en:"I am __in line__ to __check in__.",tc:"報到；辦理登機手續"}]},{id:"phrase-passed-through",phrase:"passed through",meaning:"通過某處或某程序",examples:[{en:"We __passed through__ the **security** **checkpoint**.",tc:"通過某處或某程序"}]},{id:"phrase-take-out",phrase:"take out",meaning:"拿出來",examples:[{en:"You have to __take out__ anything **metal**.",tc:"拿出來"}]},{id:"phrase-got-through",phrase:"got through",meaning:"完成並通過困難或檢查",examples:[{en:"Once we __got through__ security, we were in.",tc:"完成並通過困難或檢查"}]},{id:"phrase-made-our-way",phrase:"made our way",meaning:"前往；一路走去",examples:[{en:"We __made our way__ to our **gate**.",tc:"前往；一路走去"}]},{id:"phrase-in-a-hurry",phrase:"in a hurry",meaning:"很趕；匆忙",examples:[{en:"You're not super **rushed** or __in a hurry__.",tc:"很趕；匆忙"}]},{id:"phrase-take-off",phrase:"take off",meaning:"飛機起飛",examples:[{en:"And then we are ready to __take off__.",tc:"飛機起飛"}]},{id:"phrase-put-on",phrase:"put on",meaning:"戴上；穿上",examples:[{en:"I'm ready to __put on__ my sleep mask.",tc:"戴上；穿上"}]},{id:"phrase-sleeping-through",phrase:"sleeping through",meaning:"一路睡過整段時間",examples:[{en:"The best way to spend a flight is __sleeping through__ it.",tc:"一路睡過整段時間"}]},{id:"phrase-work-on",phrase:"work on",meaning:"處理；使用某物工作",examples:[{en:"I like to __work on__ my computer.",tc:"處理；使用某物工作"}]},{id:"phrase-get-off",phrase:"get off",meaning:"下車；下飛機",examples:[{en:"I wait my turn to __get off__ the plane.",tc:"下車；下飛機"}]},{id:"phrase-passport-control",phrase:"passport control",meaning:"護照查驗處；入出境查驗",examples:[{en:"There is normally an escalator to get to **immigration**, or __passport control__.",tc:"護照查驗處；入出境查驗"}]},{id:"phrase-stop-by",phrase:"stop by",meaning:"順道拜訪；順路去",examples:[{en:"I usually __stop by__ the food court.",tc:"順道拜訪；順路去"}]},{id:"phrase-sit-down",phrase:"sit down",meaning:"坐下",examples:[{en:"You can drive them and __sit down__ on them.",tc:"坐下"}]},{id:"phrase-pass-by",phrase:"pass by",meaning:"從眼前經過",examples:[{en:"You wait until you see your luggage __pass by__.",tc:"從眼前經過"}]},{id:"phrase-stressed-out",phrase:"stressed out",meaning:"壓力很大；焦慮",examples:[{en:"I was so __stressed out__ about getting Wi-Fi to work.",tc:"壓力很大；焦慮"}]}],l=[{id:"usage-take-item",word:"take",familiarMeaning:"拿；帶",usage:"搭乘交通工具或班機",translation:"搭飛機",examples:["We are going to 《take》 a flight."]},{id:"usage-flying-item",word:"flying",familiarMeaning:"飛；正在飛",usage:"搭乘某航空公司的班機",translation:"搭 AirAsia",examples:["We were 《flying》 with AirAsia."]},{id:"usage-real-item",word:"real",familiarMeaning:"真的",usage:"指真人，而不是機器或系統",translation:"真人",examples:["A counter with a 《real》 person."]},{id:"usage-board-item",word:"board",familiarMeaning:"板子；黑板",usage:"作動詞，表示登上飛機、船或車",translation:"登機",examples:["We waited in line to 《board》."]},{id:"usage-land-item",word:"land",familiarMeaning:"土地",usage:"作動詞，表示飛機降落",translation:"降落",examples:["I think it's almost time to 《land》."]},{id:"usage-final-final-destination",word:"final",familiarMeaning:"最後的",usage:"final destination 指旅程最後要到的目的地",translation:"最終目的地",examples:["This gate is to get me to my 《final》 destination."]},{id:"usage-miss-item",word:"miss",familiarMeaning:"想念",usage:"錯過交通工具、機會或活動",translation:"錯過航班",examples:["You might 《miss》 your flight."]},{id:"usage-checked-checked-a-bag",word:"checked",familiarMeaning:"檢查了",usage:"checked a bag 指托運行李",translation:"托運了行李",examples:["If you 《checked》 a bag."]}],h=[{id:"grammar-1",sentence:"The automatic doors slide open, and right away you see the FIDS board, the flight information display system, where you can see your flight status.",translation:"自動門滑開，然後你馬上會看到 FIDS 看板，也就是航班資訊顯示系統；在那裡你可以看到你的航班狀態。",points:[{label:"where 引導非限定關係子句",text:"名詞 + where + 主詞 + 動詞",note:"where 補充說明前面的地點或系統，在那個地方可以看到航班狀態。"}]},{id:"grammar-2",sentence:"You can see your flight status, whether it's on time, delayed, or cancelled.",translation:"你可以看到你的航班狀態，看它是準時、延誤，還是取消。",points:[{label:"whether A, B, or C",text:"whether + 主詞 + be + A, B, or C",note:"whether 用來列出幾種可能情況，表示不確定是哪一種。"}]},{id:"grammar-3",sentence:"I prefer to check in at a counter with a real person.",translation:"我比較喜歡在櫃台跟真人報到。",points:[{label:"prefer to + 原形動詞",text:"prefer + to + V",note:"用來表達比較喜歡做某件事。"}]},{id:"grammar-4",sentence:"Once we got through security, we were in.",translation:"我們一通過安檢，就進去了。",points:[{label:"once 引導時間副詞子句",text:"once + 主詞 + 動詞, 主句",note:"once 表示一旦某件事完成，接著就發生主句的結果。"}]},{id:"grammar-5",sentence:"It was super useful that they put how long a walk it was to each gate.",translation:"它們標出走到每個登機門要多久，真的非常有用。",points:[{label:"It is + 形容詞 + that 子句",text:"It + be + adjective + that + 主詞 + 動詞",note:"先用 it 當形式主詞，把真正的內容放在 that 子句中。"}]},{id:"grammar-6",sentence:"Have you ever tried one of these little sweet treats?",translation:"你有試過這種小甜點嗎？",points:[{label:"現在完成式疑問句",text:"Have + 主詞 + ever + 過去分詞?",note:"用來詢問到目前為止是否曾經有過某種經驗。"}]},{id:"grammar-7",sentence:"The plane drives on the runway for a little while, and once it gains enough speed, we take off.",translation:"飛機會在跑道上行駛一小段時間，等它取得足夠速度後，我們就起飛了。",points:[{label:"once + 現在簡單式表示時間條件",text:"once + 主詞 + 現在式動詞, 主句",note:"在時間副詞子句中，即使說的是即將發生的事，也常用現在式。"}]},{id:"grammar-8",sentence:"I love how they tint the windows so that even if it's sunny outside, it will seem like it's nighttime.",translation:"我很喜歡他們把窗戶調暗；這樣就算外面陽光很大，看起來也會像晚上。",points:[{label:"so that + even if 複合句",text:"so that + 子句 + even if + 子句",note:"so that 表目的或結果，even if 表示即使某情況成立，結果仍然一樣。"}]},{id:"grammar-9",sentence:"But if you have a layover, you normally still have to go through passport control, depending on the country.",translation:"但如果你有轉機，你通常還是要通過護照查驗，這取決於國家。",points:[{label:"depending on + 名詞",text:"主句 + depending on + 名詞",note:"depending on 表示結果會依照某個條件而不同。"}]},{id:"grammar-10",sentence:"I was so stressed out about getting Wi-Fi to work, working on my videos, editing, and answering emails that I forgot my passport.",translation:"我當時非常焦慮，忙著讓 Wi-Fi 能用、處理影片、剪輯和回覆電子郵件，結果我忘了我的護照。",points:[{label:"so + 形容詞 + that 結果子句",text:"so + adjective + that + 主詞 + 動詞",note:"表示程度高到造成某個結果。"}]}],g={level:"b1",slug:"ch17-slow-english-practice-airport-essentials-for-traveling",sourcePath:"_private/tmp/originalContent/b1/ch17-slow-english-practice-airport-essentials-for-traveling.json",proofreadPath:"C:/Users/Gary/Documents/Slowy_Learning_Eng/_private/tmp/step1/b1/ch17-slow-english-practice-airport-essentials-for-traveling.md"},p={videoId:e,slug:t,level:"b1",title:a,youtubeUrl:n,header:r,scenes:i,vocabGroups:s,phrases:o,usages:l,breakdowns:h,sourceTraceability:g};export{h as breakdowns,p as default,r as header,c as level,o as phrases,i as scenes,t as slug,g as sourceTraceability,a as title,l as usages,e as videoId,s as vocabGroups,n as youtubeUrl};
